<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { api, paths, preferences, setDemo, displayDate } from '../api'
import Chart from '../components/Chart.vue'
const data = ref(null), loading = ref(false), refreshing = ref(false), error = ref(''), message = ref('')
const kind = computed(() => preferences.demo ? 'demo' : 'public')
let epoch = 0
const statusNames = { completed: '处理完成', unchanged: '来源无变化', running: '处理中', blocked: '来源受限', failed: '处理失败', partial: '部分完成', demo_fallback: '使用模拟回退', no_data: '没有可用数据', success: '采集完成' }
const percent = value => `${(100 * value).toFixed(1)}%`
const miningChart = computed(() => ({ tooltip: { trigger: 'axis', confine: true, renderMode: 'richText' }, grid: { left: 20, right: 35, top: 15, bottom: 25, containLabel: true },
  xAxis: { type: 'value', minInterval: 1, name: '公告数' }, yAxis: { type: 'category', inverse: true, data: (data.value?.rules || []).filter(r => r.antecedent < r.consequent).slice(0, 10).map(r => `${r.antecedent} + ${r.consequent}`), axisLabel: { width: 150, overflow: 'truncate' } },
  series: [{ type: 'bar', barMaxWidth: 24, itemStyle: { color: '#62967e' }, data: (data.value?.rules || []).filter(r => r.antecedent < r.consequent).slice(0, 10).map(r => r.pair_count) }] }))
async function load() {
  const id = ++epoch, scope = kind.value
  loading.value = true; error.value = ''; data.value = null
  try { const result = await api(`/admin/data-pipeline?data_kind=${scope}`); if (id === epoch) data.value = result }
  catch(e) { if (id === epoch) error.value = e.message }
  finally { if (id === epoch) loading.value = false }
}
async function refresh() {
  const id = ++epoch, scope = kind.value
  refreshing.value = true; error.value = ''; message.value = ''
  try {
    const result = await api(`/admin/data-pipeline/refresh?data_kind=${scope}`, { method: 'POST' })
    if (id !== epoch) return
    message.value = `任务 #${result.run_id}：${statusNames[result.status]}，${result.opportunities} 条最新公告，${result.rules} 条技能规则。`
    await load()
  } catch(e) { if (id === epoch) error.value = e.message }
  finally { if (scope === kind.value) refreshing.value = false }
}
watch(kind, () => { refreshing.value = false; message.value = ''; load() })
onMounted(load)
onBeforeUnmount(() => { epoch++ })
</script>

<template>
  <div class="page-heading"><div><div class="eyebrow">FROM SOURCE TO DECISION</div><h1>数据加工全景<span class="heading-dot">.</span></h1><p>查看数据如何接入、清洗、保存和计算，再追溯每一份应用结果。</p></div><button class="button" :disabled="refreshing || loading" @click="refresh">{{ refreshing ? '正在计算…' : '刷新仓库与挖掘结果' }}</button></div>
  <div class="tabbar"><button :class="{active:!preferences.demo}" @click="setDemo(false)">公开公告</button><button :class="{active:preferences.demo}" @click="setDemo(true)">模拟演示</button></div>
  <p v-if="error" class="alert error" role="alert">{{ error }} <button class="ghost" @click="load">重试</button></p><p v-if="message" class="alert success" role="status">{{ message }}</p><p v-if="loading" role="status">正在读取处理记录…</p>
  <template v-if="data">
    <p class="alert demo">{{ data.notice }}</p>
    <section class="panel"><div class="panel-heading"><h2>从来源到应用的五步流程</h2><RouterLink to="/journey">查看学生与管理员业务路线 →</RouterLink></div><ol class="pipeline-flow" aria-label="采集清洗仓库挖掘业务流程"><li><strong>① 数据接入</strong><p>官方公告 / 问卷文件 / 高校资料</p><RouterLink to="/admin?tab=crawler">启动网页采集 →</RouterLink><RouterLink to="/admin/surveys">导入问卷文件 →</RouterLink></li><li><strong>② 数据清洗</strong><p>校验授权、字段、重复与缺失</p><a href="#cleaning-results">查看清洗结果 ↓</a></li><li><strong>③ 分层入仓</strong><p>原始来源 → 标准事实 → 主题汇总</p><a href="#warehouse-layers">查看数据仓库 ↓</a></li><li><strong>④ 数据挖掘</strong><p>计算真实的技能共同出现次数</p><a href="#mining-results">核对技能规则 ↓</a></li><li><strong>⑤ 辅助决策</strong><p>观察机会 → 个人比较 → 行动复盘</p><RouterLink to="/analytics">数据洞察 →</RouterLink><RouterLink to="/decisions">辅助决策 →</RouterLink></li></ol></section>
    <section id="warehouse-layers" class="panel"><h2>数据仓库 · 实际存储与计算</h2><p class="data-note">{{ data.storage }}</p><div class="layer-grid"><article v-for="layer in data.layers" :key="layer.code"><span class="tag">{{ layer.code }}</span><h3>{{ layer.name }}</h3><strong class="layer-count">{{ layer.rows }}</strong><p>{{ layer.unit }}</p><p>{{ layer.description }}</p><code v-for="table in layer.tables" :key="table">{{ table }}</code></article></div><p class="data-note">{{ data.application }}</p><p v-if="data.school_data" class="data-note">高校资料独立入仓：{{ data.school_data.datasets }} 个原始来源，{{ data.school_data.universities }} 所高校、{{ data.school_data.majors }} 个专业明细，均标记用户提供 / 待核验。<RouterLink to="/school">核对学校资料 →</RouterLink></p></section>
    <section class="panel"><h2>当前汇总快照与血缘</h2><template v-if="data.snapshot"><p class="data-note">最近计算：{{ displayDate(data.snapshot.refreshed_at) }} · 任务 #{{ data.snapshot.run_id }} · 规则 {{ data.snapshot.mining.algorithm_version }}</p><p v-if="data.snapshot.stale" class="alert demo">来源已有更新。点击“刷新仓库与挖掘结果”后，以下快照和规则才会更新。</p><div class="quality-grid"><div><span>全部最新公告</span><strong>{{ data.snapshot.summary.opportunities }}</strong></div><div><span>含已知技能公告</span><strong>{{ data.snapshot.summary.known_skill_records }}</strong></div><div><span>发布日期未知</span><strong>{{ data.snapshot.summary.publication_unknown }}</strong></div><div><span>截止日期未知</span><strong>{{ data.snapshot.summary.deadline_unknown }}</strong></div></div><dl class="lineage"><dt>输入事实表</dt><dd>{{ data.snapshot.lineage.source_table }}</dd><dt>版本规则</dt><dd>{{ data.snapshot.lineage.version_rule }}</dd><dt>清洗规则</dt><dd>{{ data.snapshot.lineage.normalization }}</dd><dt>来源指纹 SHA-256</dt><dd>{{ data.snapshot.source_fingerprint }}</dd><dt>关联原始网页快照</dt><dd>{{ data.snapshot.lineage.raw_document_count }} 条</dd><dt>不参与技能计算的输入</dt><dd>{{ data.snapshot.lineage.excluded_inputs.join('、') }}</dd></dl><details><summary>查看输入记录编号与输出表</summary><p class="data-note">机会快照 ID：{{ data.snapshot.lineage.source_ids.join('、') || '暂无' }}</p><p class="data-note">原文快照 ID：{{ data.snapshot.lineage.raw_document_ids.join('、') || '暂无' }}</p><p class="data-note">输出：{{ data.snapshot.lineage.target_tables.join('、') }}</p></details></template><div v-else class="empty">当前范围尚无计算快照。接入数据后点击“刷新仓库与挖掘结果”；空数据也会留下可核对的计算记录。</div></section>
    <section id="mining-results" class="panel"><div class="panel-heading"><h2>技能组合挖掘</h2><span class="tag">二项频繁项集与有向规则</span></div><template v-if="data.snapshot"><p>{{ data.snapshot.mining.notice }}</p><p class="data-note">最低样本 {{ data.snapshot.mining.minimum_population }} 条，组合至少出现 {{ data.snapshot.mining.minimum_pair_count }} 次。实际分母 {{ data.snapshot.mining.population }} 条最新公告，技能未知 {{ data.snapshot.mining.missing_skill_population }} 条；含已过期公告，表示所收集样本的描述统计。</p><p class="data-note">支持度：{{ data.snapshot.mining.support_definition }}。置信度：{{ data.snapshot.mining.confidence_definition }}。</p><Chart v-if="data.rules.length" :option="miningChart" label="公告技能组合共同出现次数"/><p v-else class="empty">{{ data.snapshot.mining.status === 'insufficient_sample' ? '样本量不足，暂不生成技能规则。' : '没有达到最小共同出现次数的技能组合。' }}</p><div v-if="data.rules.length" class="table-scroll"><table aria-label="技能共现挖掘结果"><thead><tr><th>技能前项 → 后项</th><th>共同出现 / 总公告</th><th>前项公告数</th><th>支持度</th><th>置信度</th></tr></thead><tbody><tr v-for="rule in data.rules" :key="`${rule.antecedent}:${rule.consequent}`"><td>{{ rule.antecedent }} → {{ rule.consequent }}</td><td>{{ rule.pair_count }} / {{ rule.population }}</td><td>{{ rule.antecedent_count }}</td><td>{{ percent(rule.support) }}</td><td>{{ percent(rule.confidence) }}</td></tr></tbody></table></div><p class="data-note">保留 {{ data.snapshot.mining.stored_rule_count }} / {{ data.snapshot.mining.eligible_rule_count }} 条达标规则，最多 {{ data.snapshot.mining.rule_limit }} 条；双向规则分别解释各自前项分母。</p></template><p v-else class="empty">先刷新计算，再查看技能组合。</p></section>
    <section class="panel"><div class="panel-heading"><h2>网页采集运行记录</h2><RouterLink to="/admin?tab=crawler">去采集公告 →</RouterLink></div><p>实际联网遵循 robots、来源范围与请求间隔。网络阻断会记录失败原因；模拟回退有独立数据标记，不能作为真实采集成功。</p><div class="table-scroll"><table aria-label="网页采集运行记录"><thead><tr><th>任务 / 来源</th><th>结果</th><th>新增 / 重复 / 拒绝</th><th>原因</th><th>日期</th></tr></thead><tbody><tr v-for="run in data.crawls" :key="run.id"><td>#{{ run.id }} · {{ run.source_id }}</td><td>{{ statusNames[run.status] || run.status }}</td><td>{{ run.accepted }} / {{ run.duplicates }} / {{ run.rejected }}</td><td>{{ run.errors.map(e=>e.message).join('；') || '—' }}</td><td>{{ displayDate(run.started_at) }}</td></tr></tbody></table></div><p v-if="!data.crawls.length" class="empty">当前范围暂无采集记录。</p></section>
    <section id="cleaning-results" class="panel"><div class="panel-heading"><h2>接入与清洗质量</h2><RouterLink to="/admin/surveys">打开问卷导入向导 →</RouterLink></div><p class="data-note">{{ data.batches_notice }}</p><div class="table-scroll"><table aria-label="清洗批次质量"><thead><tr><th>批次 / 规则</th><th>类型</th><th>输入</th><th>接受</th><th>拒绝</th><th>重复</th><th>日期</th></tr></thead><tbody><tr v-for="batch in data.batches" :key="batch.id"><td>#{{ batch.id }} · {{ batch.cleaning_version }}</td><td>{{ {demo:'模拟',authorized:'授权问卷或去向',public:'公开公告'}[batch.data_kind] || batch.data_kind }}</td><td>{{ batch.total }}</td><td>{{ batch.accepted }}</td><td>{{ batch.rejected }}</td><td>{{ batch.duplicates }}</td><td>{{ displayDate(batch.created_at) }}</td></tr></tbody></table></div><details v-for="batch in data.batches.filter(b=>b.errors.length)" :key="batch.id"><summary>批次 #{{ batch.id }} · 校验问题</summary><p v-for="(item,i) in batch.errors" :key="i" class="data-note">{{ item.line ? `第 ${item.line} 行：` : '' }}{{ item.message }}</p></details><p v-if="!data.batches.length" class="empty">暂无导入批次。</p></section>
    <section class="panel"><h2>最近计算任务</h2><div class="table-scroll"><table aria-label="仓库刷新任务"><thead><tr><th>任务</th><th>结果</th><th>输入公告</th><th>汇总单元</th><th>技能规则</th><th>日期</th></tr></thead><tbody><tr v-for="run in data.runs" :key="run.id"><td>#{{ run.id }}</td><td>{{ statusNames[run.status] || run.status }}</td><td>{{ run.input_count }}</td><td>{{ run.aggregate_count }}</td><td>{{ run.rule_count }}</td><td>{{ displayDate(run.finished_at) }}</td></tr></tbody></table></div><p v-if="!data.runs.length" class="empty">暂无计算任务。</p></section>
  </template>
</template>

<style scoped>
.pipeline-flow{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));padding:0;list-style:none;gap:12px;margin:20px 0 0}.pipeline-flow li{padding:15px;background:#f0f5ea;border:1px solid #dfe8d7;border-radius:7px}.pipeline-flow p{font-size:11px;margin:8px 0}.pipeline-flow a{display:block;font-size:11px;margin-top:8px}.layer-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px}.layer-grid article{padding:18px;background:#fafbf7;border:1px solid var(--line);border-radius:7px}.layer-grid h3{margin:9px 0}.layer-count{font-size:30px;color:#47765c}.layer-grid p{font-size:11px;margin-bottom:10px}.layer-grid code{display:block;font-size:10px;overflow-wrap:anywhere;color:#547561}.lineage{display:grid;grid-template-columns:150px minmax(0,1fr);gap:10px;font-size:12px}.lineage dt{color:#7c8e80}.lineage dd{margin:0;overflow-wrap:anywhere}details{margin-top:13px}summary{cursor:pointer;font-size:12px;color:#476d54}table{font-size:12px}td{overflow-wrap:anywhere}section{scroll-margin-top:15px}@media(max-width:1100px){.pipeline-flow{grid-template-columns:repeat(3,minmax(0,1fr))}.layer-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:640px){.pipeline-flow{grid-template-columns:1fr}.layer-grid{grid-template-columns:1fr 1fr;gap:8px}.layer-grid article{padding:12px}.lineage{grid-template-columns:1fr;gap:4px}.lineage dd{margin-bottom:10px}.page-heading{flex-direction:column;align-items:flex-start}}
</style>
